import React, { useEffect } from "react";
import { Component } from "./Component";
import "./Section.css";

export const Section = () => {
  // Add useEffect to load the Spline viewer after component mounts
  useEffect(() => {
    // Create a script element to load Spline
    const splineScript = document.createElement('script');
    splineScript.type = 'module';
    splineScript.src = 'https://unpkg.com/@splinetool/viewer@0.9.506/build/spline-viewer.js';
    document.head.appendChild(splineScript);

    return () => {
      // Clean up on unmount
      document.head.removeChild(splineScript);
    };
  }, []);

  return (
    <div className="section">
      <div className="hero-section">
        <div className="hero-copy">
          <div className="hero-content">
            <div className="subtitle">TAILORED AI SOLUTIONS</div>

            <div className="heading">
              <div className="main-heading">
                <div className="heading-container">
                  <div className="heading-part">Unlock</div>

                  <div className="div">
                    <div className="heading-highlight">AI</div>

                    <div className="text-wrapper"> capabilities</div>
                  </div>
                </div>

                <div className="subheading">with our customized services</div>
              </div>
            </div>

            <p className="description">
              Enhance your business outcomes by streamlining and automating your
              processes with our custom AI solutions.
            </p>
          </div>

          <Component
            className="button"
            divClassName="component-2"
            text1="Talk to our experts"
            variant="one"
          />
        </div>

        <div className="hero-svg-fill">
          <div className="spline-container">
            {/* Spline 3D viewer */}
            <spline-viewer url="https://my.spline.design/aiassistanthoverandclickinteraction-TR97XkBB1BtMJ52hfx5txP06/"></spline-viewer>

            {/* AI text overlay */}
            <div className="ai-text-overlay">AI</div>
          </div>
        </div>
      </div>
    </div>
  );
};
